$code = @'
async function(eda) {
  const project = await eda.dmt_Project.getCurrentProjectInfo();
  const doc = await eda.dmt_SelectControl.getCurrentDocumentInfo();
  const comps = await eda.pcb_PrimitiveComponent.getAll();
  const list = [];
  for (const c of comps) {
    list.push({
      designator: c.getState_Designator(),
      name: c.getState_Name(),
      x: c.getState_X(),
      y: c.getState_Y(),
      layer: c.getState_Layer(),
      rotation: c.getState_Rotation(),
      id: c.getState_PrimitiveId()
    });
  }
  return {
    project: project ? { name: project.friendlyName || project.name, uuid: project.uuid } : null,
    doc: doc ? { type: doc.documentType, name: doc.name } : null,
    componentCount: list.length,
    components: list
  };
}
